CREATE TABLE periods (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    start_year INTEGER NOT NULL,
    end_year INTEGER NOT NULL,
    category TEXT, -- 'Dynasty', 'Climate', 'Regnal', etc.
    description TEXT
);
